using DysonNetwork.Shared.Auth;
using DysonNetwork.Shared.Capabilities;
using DysonNetwork.Shared.Models;
using DysonNetwork.Shared.Networking;
using Microsoft.AspNetCore.Mvc;

namespace DysonNetwork.Passport.Account;

/// <summary>
/// Controller for managing user presence activities with lease-based expiration.
/// Supports both user-defined manual IDs and autogenerated GUIDs for activity management.
/// </summary>
[ApiController]
[Route("/api/activities")]
[ApiFeature("presences.activities", Revision = 1)]
public class PresenceActivityController(
    AccountEventService service,
    AccountService accounts,
    PresenceArtworkService artworkService
) : ControllerBase
{
    /// <summary>
    /// Retrieves active (non-expired) presence activities for the authenticated user.
    /// Optionally includes expired activities if includeExpired is true.
    /// Supports filtering by queryable presence fields and type.
    /// </summary>
    /// <param name="includeExpired">Whether to include expired activities</param>
    /// <param name="offset">The number of activities to skip for pagination</param>
    /// <param name="take">The maximum number of activities to return</param>
    /// <param name="query">Search keyword for title, subtitle, caption, manualId, provider, referenceId, or queryableTerms</param>
    /// <param name="type">Filter by presence activity type</param>
    /// <param name="provider">Filter by upstream provider such as steam or spotify</param>
    /// <param name="referenceId">Filter by upstream object identifier</param>
    /// <param name="term">Filter by normalized queryable term</param>
    /// <param name="category">Filter by presence category</param>
    /// <param name="visibility">Filter by presence visibility</param>
    /// <param name="catalogId">Filter by catalog item id</param>
    /// <param name="from">Only include sessions started at or after this instant</param>
    /// <param name="to">Only include sessions started before this instant</param>
    /// <returns>List of presence activities</returns>
    [HttpGet]
    [ProducesResponseType<List<SnPresenceActivity>>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<ActionResult<List<SnPresenceActivity>>> GetActivities(
        [FromQuery] bool includeExpired = false,
        [FromQuery] int offset = 0,
        [FromQuery] int take = 20,
        [FromQuery] string? query = null,
        [FromQuery] string? type = null,
        [FromQuery] string? provider = null,
        [FromQuery] string? referenceId = null,
        [FromQuery] string? term = null,
        [FromQuery] string[]? tags = null,
        [FromQuery] PresenceVisibility? visibility = null,
        [FromQuery] string? catalogId = null,
        [FromQuery] DateTimeOffset? from = null,
        [FromQuery] DateTimeOffset? to = null
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        var hasFilters = !string.IsNullOrWhiteSpace(query)
            || !string.IsNullOrWhiteSpace(type)
            || !string.IsNullOrWhiteSpace(provider)
            || !string.IsNullOrWhiteSpace(referenceId)
            || !string.IsNullOrWhiteSpace(term)
            || (tags is { Length: > 0 })
            || visibility.HasValue
            || !string.IsNullOrWhiteSpace(catalogId)
            || from.HasValue
            || to.HasValue;

        if (!includeExpired && !hasFilters)
        {
            var activities = await service.GetActiveActivities(currentUser.Id);
            return Ok(activities);
        }

        var (results, total) = await service.GetFilteredActivities(
            currentUser.Id,
            offset,
            take,
            query,
            type,
            provider,
            referenceId,
            term,
            isActive: includeExpired ? null : true,
            tags: tags,
            visibility: visibility,
            catalogId: catalogId,
            from: from.HasValue ? NodaTime.Instant.FromDateTimeOffset(from.Value) : null,
            to: to.HasValue ? NodaTime.Instant.FromDateTimeOffset(to.Value) : null);

        Response.Headers["X-Total"] = total.ToString();
        return Ok(results);
    }

    /// <summary>
    /// Retrieves active presence activities for any user account (admin/debugging endpoint).
    /// </summary>
    /// <returns>List of active presence activities</returns>
    [HttpGet("{identifier}")]
    [ProducesResponseType<List<SnPresenceActivity>>(StatusCodes.Status200OK)]
    public async Task<ActionResult<List<SnPresenceActivity>>> GetActivitiesByAccountId(
        string identifier
    )
    {
        var account = Guid.TryParse(identifier, out var identifierGuid)
            ? await accounts.GetAccount(identifierGuid)
            : await accounts.LookupAccount(identifier);
        if (account is null)
            return NotFound(new ApiError { Code = "PASSPORT_ACCOUNT_NOT_FOUND", Message = "Account not found.", Status = 404, TraceId = HttpContext.TraceIdentifier });

        var activities = await service.GetActiveActivities(account.Id);
        return Ok(activities);
    }

    /// <summary>
    /// Creates or updates a presence activity with lease expiration.
    /// If an activity with the same 'manualId' exists, it will be updated.
    /// Otherwise, a new activity will be created.
    /// </summary>
    /// <param name="request">Activity creation or update parameters</param>
    /// <returns>The created or updated activity</returns>
    [HttpPost]
    [ProducesResponseType<SnPresenceActivity>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<SnPresenceActivity>> SetActivity(
        [FromBody] SetActivityRequest request,
        CancellationToken cancellationToken
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        try
        {
            await artworkService.ValidateAndTouchReferencesAsync(
                [request.LargeImage, request.SmallImage],
                cancellationToken
            );
        }
        catch (KeyNotFoundException ex)
        {
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ARTWORK_NOT_FOUND", Message = ex.Message, Status = 400, TraceId = HttpContext.TraceIdentifier });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ARTWORK_INVALID", Message = ex.Message, Status = 400, TraceId = HttpContext.TraceIdentifier });
        }

        if (!string.IsNullOrWhiteSpace(request.ManualId))
        {
            var result = await service.UpdateActivityByManualId(
                request.ManualId,
                currentUser.Id,
                activity =>
                {
                    if (!string.IsNullOrWhiteSpace(request.Type))
                        activity.Type = request.Type.Trim();
                    activity.Provider = NormalizeProvider(request.Provider);
                    activity.ReferenceId = NormalizeNullableField(request.ReferenceId);
                    activity.Title = request.Title;
                    activity.Subtitle = request.Subtitle;
                    activity.Caption = request.Caption;
                    activity.LargeImage = request.LargeImage;
                    activity.SmallImage = request.SmallImage;
                    activity.TitleUrl = request.TitleUrl;
                    activity.SubtitleUrl = request.SubtitleUrl;
                    activity.QueryableTerms = NormalizeQueryableTerms(request.QueryableTerms);
                    activity.Meta = request.Meta;
                },
                request.LeaseMinutes
            );

            if (result != null)
            {
                return Ok(result);
            }
        }

        if (string.IsNullOrWhiteSpace(request.Type))
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_TYPE_REQUIRED", Message = "Type is required when creating a new activity.", Status = 400, TraceId = HttpContext.TraceIdentifier });

        var newActivity = new SnPresenceActivity
        {
            AccountId = currentUser.Id,
            Type = request.Type.Trim(),
            Provider = NormalizeProvider(request.Provider),
            ReferenceId = NormalizeNullableField(request.ReferenceId),
            ManualId = request.ManualId,
            Title = request.Title,
            Subtitle = request.Subtitle,
            Caption = request.Caption,
            LargeImage = request.LargeImage,
            SmallImage = request.SmallImage,
            TitleUrl = request.TitleUrl,
            SubtitleUrl = request.SubtitleUrl,
            QueryableTerms = NormalizeQueryableTerms(request.QueryableTerms),
            Meta = request.Meta,
        };

        var createResult = await service.SetActivity(newActivity, request.LeaseMinutes);
        return Ok(createResult);
    }

    /// <summary>
    /// Starts a presence session with catalog accumulation.
    /// Re-starting the same manualId refreshes the active session instead of creating a new row.
    /// </summary>
    /// <param name="request">Session start parameters</param>
    /// <returns>The started session activity</returns>
    [HttpPost("sessions/start")]
    [ApiFeature("presences.activities", Revision = 2)]
    [ProducesResponseType<SnPresenceActivity>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<SnPresenceActivity>> StartActivitySession(
        [FromBody] StartSessionRequest request,
        CancellationToken cancellationToken
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        if (string.IsNullOrWhiteSpace(request.ManualId))
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_MANUAL_ID_REQUIRED", Message = "ManualId is required.", Status = 400, TraceId = HttpContext.TraceIdentifier });

        try
        {
            await artworkService.ValidateAndTouchReferencesAsync(
                [request.LargeImage, request.SmallImage],
                cancellationToken
            );
        }
        catch (KeyNotFoundException ex)
        {
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ARTWORK_NOT_FOUND", Message = ex.Message, Status = 400, TraceId = HttpContext.TraceIdentifier });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ARTWORK_INVALID", Message = ex.Message, Status = 400, TraceId = HttpContext.TraceIdentifier });
        }

        if (string.IsNullOrWhiteSpace(request.Type))
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_TYPE_REQUIRED", Message = "Type is required when starting a session.", Status = 400, TraceId = HttpContext.TraceIdentifier });

        var result = await service.StartActivitySession(
            currentUser.Id,
            request.ManualId,
            request.Type.Trim(),
            request.Tags,
            NormalizeProvider(request.Provider),
            NormalizeNullableField(request.ReferenceId),
            request.Title,
            request.Subtitle,
            request.Caption,
            request.LargeImage,
            request.SmallImage,
            request.TitleUrl,
            request.SubtitleUrl,
            NormalizeQueryableTerms(request.QueryableTerms),
            request.Meta,
            request.CatalogKey,
            request.CatalogName,
            request.Visibility,
            request.LeaseMinutes
        );

        return Ok(result);
    }

    /// <summary>
    /// Ends a presence session and accumulates its duration into the catalog item.
    /// Idempotent: ending an already-ended session returns 404.
    /// </summary>
    /// <param name="request">Session end parameters</param>
    /// <returns>The ended session activity</returns>
    [HttpPost("sessions/end")]
    [ApiFeature("presences.activities", Revision = 2)]
    [ProducesResponseType<SnPresenceActivity>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<SnPresenceActivity>> EndActivitySession(
        [FromBody] EndSessionRequest request,
        CancellationToken cancellationToken
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        if (string.IsNullOrWhiteSpace(request.ManualId))
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_MANUAL_ID_REQUIRED", Message = "ManualId is required.", Status = 400, TraceId = HttpContext.TraceIdentifier });

        var result = await service.EndActivitySession(currentUser.Id, request.ManualId);
        if (result == null)
            return NotFound(new ApiError { Code = "PASSPORT_ACTIVITY_NOT_FOUND", Message = "Activity not found.", Status = 404, TraceId = HttpContext.TraceIdentifier });

        return Ok(result);
    }

    /// <summary>
    /// Retrieves the catalog of accumulated activity items for the authenticated user.
    /// </summary>
    /// <returns>List of catalog items</returns>
    [HttpGet("catalog")]
    [ApiFeature("presences.catalog", Revision = 1)]
    [ProducesResponseType<List<SnPresenceCatalogItem>>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<ActionResult<List<SnPresenceCatalogItem>>> GetCatalog(
        [FromQuery] string[]? tags = null,
        [FromQuery] string? provider = null,
        [FromQuery] string? query = null,
        [FromQuery] bool? isActive = null,
        [FromQuery] int offset = 0,
        [FromQuery] int take = 50
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        var results = await service.GetCatalogItems(
            currentUser.Id,
            tags,
            provider,
            query,
            isActive,
            offset,
            take
        );

        return Ok(results);
    }

    /// <summary>
    /// Retrieves per-catalog accumulated duration in seconds for the authenticated user.
    /// </summary>
    /// <returns>Dictionary keyed by catalog id with total seconds</returns>
    [HttpGet("stats")]
    [ApiFeature("presences.stats", Revision = 1)]
    [ProducesResponseType<Dictionary<string, long>>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<ActionResult<Dictionary<string, long>>> GetStats(
        [FromQuery] DateTimeOffset? from = null,
        [FromQuery] DateTimeOffset? to = null,
        [FromQuery] string[]? tags = null
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        var results = await service.GetCatalogStats(
            currentUser.Id,
            from.HasValue ? NodaTime.Instant.FromDateTimeOffset(from.Value) : null,
            to.HasValue ? NodaTime.Instant.FromDateTimeOffset(to.Value) : null,
            tags
        );

        return Ok(results);
    }

    /// <summary>
    /// Retrieves per-tag accumulated duration in seconds from ended session rows.
    /// </summary>
    /// <returns>Dictionary keyed by tag slug with total seconds</returns>
    [HttpGet("tags/stats")]
    [ApiFeature("presences.stats", Revision = 1)]
    [ProducesResponseType<Dictionary<string, long>>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<ActionResult<Dictionary<string, long>>> GetTagStats(
        [FromQuery] DateTimeOffset? from = null,
        [FromQuery] DateTimeOffset? to = null
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        var results = await service.GetTagStats(
            currentUser.Id,
            from.HasValue ? NodaTime.Instant.FromDateTimeOffset(from.Value) : null,
            to.HasValue ? NodaTime.Instant.FromDateTimeOffset(to.Value) : null
        );

        return Ok(results);
    }

    /// <summary>
    /// Updates an existing presence activity using either its GUID or manual ID.
    /// </summary>
    /// <param name="id">System-generated GUID of the activity (optional)</param>
    /// <param name="request">Update parameters (only provided fields are updated)</param>
    /// <returns>The updated activity</returns>
    /// <remarks>One of 'id' or 'manualId' must be provided and non-empty.</remarks>
    [HttpPut("{id:guid}")]
    [AskPermission(PermissionKeys.PresencesActivityManage)]
    [ProducesResponseType<SnPresenceActivity>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<SnPresenceActivity>> UpdateActivity(
        [FromRoute] Guid id,
        [FromBody] SetActivityRequest request,
        CancellationToken cancellationToken
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        try
        {
            await artworkService.ValidateAndTouchReferencesAsync(
                [request.LargeImage, request.SmallImage],
                cancellationToken
            );
        }
        catch (KeyNotFoundException ex)
        {
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ARTWORK_NOT_FOUND", Message = ex.Message, Status = 400, TraceId = HttpContext.TraceIdentifier });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ARTWORK_INVALID", Message = ex.Message, Status = 400, TraceId = HttpContext.TraceIdentifier });
        }

        var result = await service.UpdateActivity(
            id,
            currentUser.Id,
            activity =>
            {
                if (!string.IsNullOrWhiteSpace(request.Type))
                    activity.Type = request.Type.Trim();
                if (request.Provider != null)
                    activity.Provider = NormalizeProvider(request.Provider);
                if (request.ReferenceId != null)
                    activity.ReferenceId = NormalizeNullableField(request.ReferenceId);
                if (request.Title != null)
                    activity.Title = request.Title;
                if (request.Subtitle != null)
                    activity.Subtitle = request.Subtitle;
                if (request.Caption != null)
                    activity.Caption = request.Caption;
                if (request.ManualId != null)
                    activity.ManualId = request.ManualId;
                if (request.LargeImage != null)
                    activity.LargeImage = request.LargeImage;
                if (request.SmallImage != null)
                    activity.SmallImage = request.SmallImage;
                if (request.QueryableTerms != null)
                    activity.QueryableTerms = NormalizeQueryableTerms(request.QueryableTerms);
                if (request.Meta != null)
                    activity.Meta = request.Meta;
            },
            request.LeaseMinutes
        );

        return Ok(result);
    }

    /// <summary>
    /// Deletes a presence activity using either its GUID or manual ID.
    /// </summary>
    /// <param name="id">System-generated GUID of the activity (optional)</param>
    /// <param name="manualId">User-defined manual ID of the activity (optional)</param>
    /// <returns>NoContent on success</returns>
    /// <remarks>One of 'id' or 'manualId' must be provided and non-empty. Soft-deletes the activity.</remarks>
    [HttpDelete]
    [AskPermission(PermissionKeys.PresencesActivityManage)]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> DeleteActivityById(
        [FromQuery] string? id,
        [FromQuery] string? manualId
    )
    {
        if (HttpContext.Items["CurrentUser"] is not SnAccount currentUser)
            return Unauthorized(new ApiError { Code = "UNAUTHORIZED", Message = "Authentication is required.", Status = 401 });

        if (!string.IsNullOrWhiteSpace(manualId))
        {
            var deleted = await service.DeleteActivityByManualId(manualId, currentUser.Id);
            if (!deleted)
                return NotFound(new ApiError { Code = "PASSPORT_ACTIVITY_NOT_FOUND", Message = "Activity not found.", Status = 404, TraceId = HttpContext.TraceIdentifier });

            return NoContent();
        }

        if (string.IsNullOrWhiteSpace(id) || !Guid.TryParse(id, out var activityGuid))
            return BadRequest(new ApiError { Code = "PASSPORT_ACTIVITY_ID_REQUIRED", Message = "Either 'id' (GUID) or 'manualId' must be provided.", Status = 400, TraceId = HttpContext.TraceIdentifier });
        {
            var deleted = await service.DeleteActivity(activityGuid, currentUser.Id);
            if (!deleted)
                return NotFound(new ApiError { Code = "PASSPORT_ACTIVITY_NOT_FOUND", Message = "Activity not found.", Status = 404, TraceId = HttpContext.TraceIdentifier });

            return NoContent();
        }
    }

    /// <summary>
    /// Request model for starting a presence session.
    /// </summary>
    public class StartSessionRequest
    {
        /// <summary>Free-form activity type (e.g. "gaming", "coding")</summary>
        public string? Type { get; set; }

        /// <summary>User-defined identifier for the session; re-starting the same id refreshes the active session</summary>
        public string? ManualId { get; set; }

        /// <summary>Upstream provider identifier such as steam or spotify</summary>
        public string? Provider { get; set; }

        /// <summary>Upstream object identifier such as a game id or track id</summary>
        public string? ReferenceId { get; set; }

        /// <summary>Main title of the activity</summary>
        public string? Title { get; set; }

        /// <summary>Secondary subtitle of the activity</summary>
        public string? Subtitle { get; set; }

        /// <summary>Additional caption/description</summary>
        public string? Caption { get; set; }

        /// <summary>Large image URL or base64 string</summary>
        public string? LargeImage { get; set; }

        /// <summary>Small image URL or base64 string</summary>
        public string? SmallImage { get; set; }

        /// <summary>Title URL</summary>
        public string? TitleUrl { get; set; }

        /// <summary>Subtitle URL</summary>
        public string? SubtitleUrl { get; set; }

        /// <summary>Normalized query terms for structured lookup such as artists, albums, app names, or platforms</summary>
        public string[]? QueryableTerms { get; set; }

        /// <summary>Extensible metadata dictionary for custom developer data</summary>
        public Dictionary<string, object?>? Meta { get; set; }

        /// <summary>Query-friendly tags: slug + human-readable name (e.g. genre, gamemode, work kind)</summary>
        public List<SnPresenceTag> Tags { get; set; } = [];

        /// <summary>Visibility of the activity to other users</summary>
        public PresenceVisibility Visibility { get; set; } = PresenceVisibility.Public;

        /// <summary>Stable key of the catalog item this session accumulates into</summary>
        public string? CatalogKey { get; set; }

        /// <summary>Display name for the catalog item (falls back to title)</summary>
        public string? CatalogName { get; set; }

        /// <summary>Lease duration in minutes (1-60, default: 5)</summary>
        public int LeaseMinutes { get; set; } = 5;
    }

    /// <summary>
    /// Request model for ending a presence session.
    /// </summary>
    public class EndSessionRequest
    {
        /// <summary>User-defined identifier of the session to end</summary>
        public string? ManualId { get; set; }
    }

    /// <summary>
    /// Request model for creating a new presence activity.
    /// </summary>
    public class SetActivityRequest
    {
        /// <summary>Free-form activity type (e.g. "gaming", "coding")</summary>
        public string? Type { get; set; }

        /// <summary>User-defined identifier for the activity (optional, for easy reference)</summary>
        public string? ManualId { get; set; }

        /// <summary>Upstream provider identifier such as steam or spotify</summary>
        public string? Provider { get; set; }

        /// <summary>Upstream object identifier such as a game id or track id</summary>
        public string? ReferenceId { get; set; }

        /// <summary>Main title of the activity</summary>
        public string? Title { get; set; }

        /// <summary>Secondary subtitle of the activity</summary>
        public string? Subtitle { get; set; }

        /// <summary>Additional caption/description</summary>
        public string? Caption { get; set; }

        /// <summary>Large image URL or base64 string</summary>
        public string? LargeImage { get; set; }

        /// <summary>Small image URL or base64 string</summary>
        public string? SmallImage { get; set; }

        /// <summary>Title URL</summary>
        public string? TitleUrl { get; set; }

        /// <summary>Subtitle URL</summary>
        public string? SubtitleUrl { get; set; }

        /// <summary>Normalized query terms for structured lookup such as artists, albums, app names, or platforms</summary>
        public string[]? QueryableTerms { get; set; }

        /// <summary>Extensible metadata dictionary for custom developer data</summary>
        public Dictionary<string, object>? Meta { get; set; }

        /// <summary>Lease duration in minutes (1-60, default: 5)</summary>
        public int LeaseMinutes { get; set; } = 5;
    }

    private static string? NormalizeNullableField(string? value)
    {
        return string.IsNullOrWhiteSpace(value) ? null : value.Trim();
    }

    private static string? NormalizeProvider(string? value)
    {
        return string.IsNullOrWhiteSpace(value) ? null : value.Trim().ToLowerInvariant();
    }

    private static string[] NormalizeQueryableTerms(IEnumerable<string>? terms)
    {
        return (terms ?? [])
            .Where(term => !string.IsNullOrWhiteSpace(term))
            .Select(term => term.Trim().ToLowerInvariant())
            .Distinct()
            .ToArray();
    }
}
